<?php session_start(); require_once __DIR__.'/../include/db.php'; $e=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $email=trim($_POST['email']??'');$p=$_POST['password']??'';$s=mysqli_prepare($conn,'SELECT id,name,password FROM admins WHERE email=?');mysqli_stmt_bind_param($s,'s',$email);mysqli_stmt_execute($s);$a=mysqli_fetch_assoc(mysqli_stmt_get_result($s));if($a&&password_verify($p,$a['password'])){$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$a['name'];header('Location: dashboard.php');exit;} $e='Invalid admin login.';} ?><!doctype html><html><body style="font-family:Arial"><div style="max-width:400px;margin:80px auto"><h1>Admin Login</h1><?php if($e)echo '<p style="color:red">'.htmlspecialchars($e).'</p>';?><form method="post"><input name="email" type="email" placeholder="Email" required style="width:100%;padding:12px"><br><br><input name="password" type="password" placeholder="Password" required style="width:100%;padding:12px"><br><br><button style="padding:12px;width:100%">Login</button></form></div></body></html>
